#import <Foundation/Foundation.h>
#import <CoreGraphics/CoreGraphics.h>
#import <ImageIO/ImageIO.h>
#import "SpotifyCover.h"
#import "music.h"
#include <assert.h>
#include <string.h>
static NSData *GrayReference(CGImageRef image){if(!image)return nil;NSMutableData *d=[NSMutableData dataWithLength:TM_COVER_BYTES];CGColorSpaceRef cs=CGColorSpaceCreateDeviceGray();CGContextRef ctx=CGBitmapContextCreate(d.mutableBytes,144,144,8,144,cs,kCGImageAlphaNone);CGColorSpaceRelease(cs);if(!ctx)return nil;CGContextSetInterpolationQuality(ctx,kCGInterpolationHigh);CGContextDrawImage(ctx,CGRectMake(0,0,144,144),image);CGContextRelease(ctx);return d;}
static CGImageRef MakeImage(size_t w,size_t h,void(^draw)(CGContextRef)){NSMutableData *d=[NSMutableData dataWithLength:w*h*4];CGColorSpaceRef cs=CGColorSpaceCreateDeviceRGB();CGContextRef c=CGBitmapContextCreate(d.mutableBytes,w,h,8,w*4,cs,kCGImageAlphaPremultipliedLast|kCGBitmapByteOrder32Big);CGColorSpaceRelease(cs);draw(c);CGImageRef img=CGBitmapContextCreateImage(c);CGContextRelease(c);return img;}
static NSData *PNG(CGImageRef image){NSMutableData *d=[NSMutableData data];CGImageDestinationRef dst=CGImageDestinationCreateWithData((__bridge CFMutableDataRef)d,CFSTR("public.png"),1,NULL);assert(dst);CGImageDestinationAddImage(dst,image,NULL);assert(CGImageDestinationFinalize(dst));CFRelease(dst);return d;}
int main(void){@autoreleasepool{CGImageRef sample=MakeImage(300,300,^(CGContextRef c){CGContextSetGrayFillColor(c,1,1);CGContextFillRect(c,CGRectMake(0,150,300,150));CGContextSetGrayFillColor(c,0,1);CGContextFillRect(c,CGRectMake(0,0,150,150));CGContextSetGrayFillColor(c,128.0/255.0,1);CGContextFillRect(c,CGRectMake(150,0,150,150));});NSData *png=PNG(sample);CGImageRef thumb=TMSpotifyThumbnail(png,360);assert(thumb);NSData *out=TMGrayCover(thumb),*ref=GrayReference(thumb);assert(out.length==TM_COVER_BYTES&&[out isEqualToData:ref]);CGImageRelease(thumb);CGImageRelease(sample);
CGImageRef wide=MakeImage(400,200,^(CGContextRef c){CGContextSetGrayFillColor(c,1,1);CGContextFillRect(c,CGRectMake(0,0,400,200));CGContextSetGrayFillColor(c,0,1);CGContextFillRect(c,CGRectMake(0,0,100,200));CGContextSetGrayFillColor(c,0,1);CGContextFillRect(c,CGRectMake(300,0,100,200));CGContextSetGrayFillColor(c,.5,1);CGContextFillRect(c,CGRectMake(100,0,200,200));});NSData *wideOut=TMGrayCover(wide);assert(wideOut.length==20736);const uint8_t *p=wideOut.bytes;assert(p[72*144+5]>110&&p[72*144+5]<145&&p[72*144+138]>110&&p[72*144+138]<145&&p[72*144+72]>110&&p[72*144+72]<145);CGImageRelease(wide);
assert(TMSpotifyThumbnail([@"bad png" dataUsingEncoding:NSUTF8StringEncoding],360)==NULL);NSMutableData *large=[NSMutableData dataWithLength:9*1024*1024];assert(TMSpotifyThumbnail(large,360)==NULL);puts("SpotifyCoverTests PASS");}return 0;}
